SELECT '2025Q2' AS quarter, AVG(CASE WHEN o.promo_id IS NOT NULL THEN 1.0 ELSE 0.0 END) AS rate FROM orders o WHERE NOT o.is_deleted AND o.status NOT IN ('cancelled', 'canceled', 'payment_failed') AND CAST(o.order_at AS DATE) BETWEEN DATE '2025-04-01' AND DATE '2025-06-30' UNION ALL SELECT '2026Q2' AS quarter, AVG(CASE WHEN o.promo_id IS NOT NULL THEN 1.0 ELSE 0.0 END) AS rate FROM orders o WHERE NOT o.is_deleted AND o.status NOT IN ('cancelled', 'canceled', 'payment_failed') AND CAST(o.order_at AS DATE) BETWEEN DATE '2026-04-01' AND DATE '2026-06-30'
